[SubscribesTo(classStr(NumberSeqGlobal), delegateStr(NumberSeqGlobal, buildModulesMapDelegate))]
internal static void buildModulesMapSubsciber(Map numberSeqModuleNamesMap)
{
    NumberSeqGlobal::addModuleToMap(classnum(METPODNumSeq), numberSeqModuleNamesMap);
}

    /// <summary>
    /// numberSeqModule
    /// </summary>
    /// <returns>
    /// POD number sequence enumeration
    /// </returns>
    [Hookable(false)]
    public NumberSeqModule numberSeqModule()
    {
        NumberSeqModule ret;

        ret = NumberSeqModule::Cust;

        return ret;
    }

    /// <summary>
    /// initializeReference
    /// </summary>
    /// <param name="_reference">
    ///    The instance of the <c>NumberSequenceReference</c> object to initialize.
    /// </param>
    /// <param name="_datatype">
    ///    The data type to be used by the <c>NumberSequenceReference</c> object.
    /// </param>
    /// <param name="_scope">
    ///    The scope to be used by the <c>NumberSequenceReference</c> object.
    /// </param>
    [Hookable(false)]
    public void initializeReference(NumberSequenceReference _reference, NumberSeqDatatype _datatype, NumberSeqScope _scope)
    {
        super(_reference, _datatype, _scope);

        if (_datatype.parmDatatypeId() == extendedTypeNum(METProofOfDocNumber))
        {
            _reference.AllowSameAs = true;
        }
    }

    [Hookable(false)]
    protected void loadModule()
    {
        NumberSeqDatatype datatype = NumberSeqDatatype::construct();

        datatype.parmDatatypeId(extendedtypenum(METProofOfDocNumber));
        datatype.parmReferenceHelp(literalstr("@MET:UniquePOD"));
        datatype.parmWizardIsContinuous(false);
        datatype.parmWizardfetchAheadQty(10);
        datatype.parmWizardIsManual(NoYes::No);
        datatype.parmWizardIsChangeDownAllowed(NoYes::No);
        datatype.parmWizardIsChangeUpAllowed(NoYes::No);
        datatype.parmWizardHighest(999999);
        datatype.parmSortField(4);
        
        // Create Global number sequence
        datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
        this.create(datatype);
    }
